+    private String escape(String violation) {
+        // Backslashes are escaped as well, so a carriage return in a violation is not
+        // confused with a carriage-return line separator when the file is read again.
+        return violation.replace("\\", "\\\\").replace("\r", "\\r").replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        StringBuilder result = new StringBuilder();
+        boolean escaped = false;
+        for (int i = 0; i < violation.length(); i++) {
+            char character = violation.charAt(i);
+            if (escaped) {
+                if (character == 'r') {
+                    result.append('\r');
+                } else {
+                    result.append(character);
+                }
+                escaped = false;
+            } else if (character == '\\') {
+                escaped = true;
+            } else {
+                result.append(character);
+            }
+        }
+        if (escaped) {
+            result.append('\\');
+        }
+        return result.toString();
+    }
