/**
 * A text file based implementation of a {@link ViolationStore}.<br>
 * This {@link ViolationStore} will store the violations of every single {@link FreezingArchRule} in a dedicated file.<br>
 * It will keep an index of all stored rules as well as a mapping to the individual rule violation files in the same folder.
 * <p>
 * The store can be configured through the following properties:
 * <pre><code>
 * default.path=...               # string: the path of the folder where violation files will be stored
 * default.allowStoreCreation=... # boolean: whether to allow creating a new index file
 * default.allowStoreUpdate=...   # boolean: whether to allow updating any store file
 * default.fileNames=random|description|... # how names for new violation files are derived
 * default.integrity=ignore|repair|fail     # how the index and its files are checked
 * </code></pre>
 */
@PublicAPI(usage = ACCESS)
public final class TextFileBasedViolationStore implements ViolationStore {
    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);

    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
    private static final String STORE_PATH_DEFAULT = "archunit_store";
    private static final String STORED_RULES_FILE_NAME = "stored.rules";
    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
    private static final String FILE_NAMES_RANDOM = "random";
    private static final String FILE_NAMES_DESCRIPTION = "description";
    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
    private static final String INTEGRITY_DEFAULT = "ignore";
    private static final String INTEGRITY_REPAIR = "repair";
    private static final String INTEGRITY_FAIL = "fail";

    private static final Pattern DESCRIPTION_WORD = Pattern.compile("(?<![A-Za-z0-9])([A-Za-z0-9]{4,120})(?![A-Za-z0-9])");
    private static final Map<String, FileSyncedProperties> STORED_RULES_BY_PATH = new HashMap<>();

    private final RuleViolationFileNameStrategy configuredStrategy;
    private final boolean strategyWasGivenToConstructor;

    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
    private boolean randomFileNames;
    private boolean storeCreationAllowed;
    private boolean storeUpdateAllowed;
    private File storeFolder;
    private FileSyncedProperties storedRules;
    private IntegrityMode integrityMode;

    /**
     * Creates a standard store that names new rule violation files with random UUIDs.
     */
    public TextFileBasedViolationStore() {
        this(__ -> UUID.randomUUID().toString(), false);
    }

    /**
     * Creates a store with a custom strategy for rule violation file naming.
     *
     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
     */
    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
        this(ruleViolationFileNameStrategy, true);
    }

    private TextFileBasedViolationStore(RuleViolationFileNameStrategy strategy, boolean strategyWasGivenToConstructor) {
        if (strategy == null) {
            throw new NullPointerException("ruleViolationFileNameStrategy");
        }
        configuredStrategy = strategy;
        this.strategyWasGivenToConstructor = strategyWasGivenToConstructor;
    }

    @Override
    public void initialize(Properties properties) {
        integrityMode = parseIntegrity(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Integrity mode '%s' requires %s=true", INTEGRITY_REPAIR, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        configureFileNameStrategy(properties);
        storeFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT));
        File storedRulesFile = getStoredRulesFile();
        log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesFile.getAbsolutePath());

        // A fail-mode initialization is intentionally not allowed to create the index. This is important
        // both for diagnostics and for callers that use fail mode as a read-only integrity gate.
        boolean createIndex = integrityMode != IntegrityMode.FAIL;
        storedRules = getOrCreateStoredRules(storedRulesFile, createIndex);
        checkInitialization(storedRules.initializationSuccessful(), "Cannot create rule store at %s", storedRulesFile.getAbsolutePath());

        synchronized (storedRules) {
            if (integrityMode == IntegrityMode.REPAIR || integrityMode == IntegrityMode.FAIL) {
                IntegrityReport report = inspectIntegrity(storedRules.snapshot());
                if (integrityMode == IntegrityMode.FAIL && report.hasProblems()) {
                    throw new StoreInitializationFailedException(report.asMessage(storeUpdateAllowed));
                }
                if (integrityMode == IntegrityMode.REPAIR) {
                    repairIntegrity(report);
                }
            }
        }
    }

    private IntegrityMode parseIntegrity(String value) {
        if (INTEGRITY_REPAIR.equals(value)) {
            return IntegrityMode.REPAIR;
        }
        if (INTEGRITY_FAIL.equals(value)) {
            return IntegrityMode.FAIL;
        }
        if (INTEGRITY_DEFAULT.equals(value)) {
            return IntegrityMode.IGNORE;
        }
        throw new StoreInitializationFailedException(String.format(
                "Invalid %s value '%s'; accepted values are '%s', '%s' and '%s'",
                INTEGRITY_PROPERTY_NAME, value, INTEGRITY_REPAIR, INTEGRITY_FAIL, INTEGRITY_DEFAULT));
    }

    private void configureFileNameStrategy(Properties properties) {
        if (strategyWasGivenToConstructor) {
            if (properties.getProperty(FILE_NAMES_PROPERTY_NAME) != null) {
                throw new StoreInitializationFailedException(String.format(
                throw new StoreInitializationFailedException(String.format(
                        "%s cannot be configured when a filename strategy was supplied to the constructor",
                        FILE_NAMES_PROPERTY_NAME));
            }
            ruleViolationFileNameStrategy = configuredStrategy;
            randomFileNames = false;
            return;
        }

        String configuredFileNames = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_RANDOM);
        if (FILE_NAMES_RANDOM.equals(configuredFileNames)) {
            ruleViolationFileNameStrategy = configuredStrategy;
            randomFileNames = true;
        } else if (FILE_NAMES_DESCRIPTION.equals(configuredFileNames)) {
            ruleViolationFileNameStrategy = TextFileBasedViolationStore::createDescriptionFileName;
            randomFileNames = false;
        } else {
            ruleViolationFileNameStrategy = instantiateStrategy(configuredFileNames);
            randomFileNames = false;
        }
    }

    private RuleViolationFileNameStrategy instantiateStrategy(String className) {
        try {
            Class<?> strategyClass = Class.forName(className);
            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyClass)) {
                throw new IllegalArgumentException("not a public RuleViolationFileNameStrategy");
            }
            return (RuleViolationFileNameStrategy) strategyClass.getConstructor().newInstance();
        } catch (Exception e) {
            throw new StoreInitializationFailedException(String.format(
                    "Could not instantiate %s configured by %s=%s",
                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, className), e);
        }
    }

    private FileSyncedProperties getOrCreateStoredRules(File storedRulesFile, boolean createIndex) {
        try {
            String canonicalPath = storedRulesFile.getCanonicalPath();
            synchronized (STORED_RULES_BY_PATH) {
                FileSyncedProperties existing = STORED_RULES_BY_PATH.get(canonicalPath);
                if (existing != null) {
                    return existing;
                }
                FileSyncedProperties created = new FileSyncedProperties(storedRulesFile, createIndex);
                STORED_RULES_BY_PATH.put(canonicalPath, created);
                return created;
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private File getStoredRulesFile() {
        File rulesFile = new File(storeFolder, STORED_RULES_FILE_NAME);
        if (!existsWithoutFollowingLinks(rulesFile.toPath()) && !storeCreationAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
        }
        if (integrityMode == IntegrityMode.FAIL && !existsWithoutFollowingLinks(rulesFile.toPath())) {
            throw new StoreInitializationFailedException(
                    "Integrity mode 'fail' requires an existing " + STORED_RULES_FILE_NAME + " index");
        }
        return rulesFile;
    }

    private void checkInitialization(boolean initializationSuccessful, String message, Object... args) {
        if (!initializationSuccessful) {
            throw new StoreInitializationFailedException(String.format(message, args));
        }
    }

    @Override
    public boolean contains(ArchRule rule) {
        synchronized (storedRules) {
            return storedRules.containsKey(rule.getDescription());
        }
    }

    @Override
    public void save(ArchRule rule, List<String> violations) {
        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
        if (!storeUpdateAllowed) {
            throw new StoreUpdateFailedException(String.format(
                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        synchronized (storedRules) {
            String description = rule.getDescription();
            String existingFileName = storedRules.getProperty(description);
            boolean knownRule = existingFileName != null;
            String fileName = existingFileName;

            if (!knownRule && violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
                return;
            }
            if (!knownRule) {
                fileName = requireFileName(description);
            }
            Path ruleFile = validateStoreTarget(fileName);

            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR && knownRule) {
                forgetRule(description, fileName, ruleFile);
                return;
            }

            boolean indexChanged = !knownRule;
            if (!knownRule) {
                storedRules.put(description, fileName);
            }
            try {
                write(violations, ruleFile);
                if (indexChanged) {
                    storedRules.syncFileSystem();
                }
            } catch (RuntimeException e) {
                if (indexChanged) {
                    storedRules.remove(description);
                }
                throw e;
            }
        }
    }

    @Override
    public List<String> getViolations(ArchRule rule) {
        synchronized (storedRules) {
            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
            List<String> result = readLines(ruleDetailsFileName);
            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
            return result;
        }
    }

    private void forgetRule(String description, String fileName, Path ruleFile) {
        boolean shared = isSharedEntry(description, fileName);
        if (!shared) {
            try {
                if (existsWithoutFollowingLinks(ruleFile)
                        && !(Files.isSymbolicLink(ruleFile) && !Files.exists(ruleFile))) {
                    if (!isRegularFileDirectly(ruleFile)) {
                        throw new IOException("The stored rule path does not lead to a regular file: " + ruleFile);
                    }
