+            char character = violation.charAt(i);
+            if (escaped) {
+                if (character == 'r') {
+                    result.append('\r');
+                } else {
+                    result.append(character);
+                }
+                escaped = false;
+            } else if (character == '\\') {
+                escaped = true;
+            } else {
+                result.append(character);
+            }
+        }
