+        int backslashes = 0;
+        for (int i = 0; i < text.length(); i++) {
+            char character = text.charAt(i);
+            if (character == '\\') {
+                line.append(character);
+                backslashes++;
+            } else if (character == '\n') {
+                if (backslashes % 2 == 1) {
+                    line.append(character);
+                } else {
+                    addViolation(result, line);
+                    line.setLength(0);
+                }
+                backslashes = 0;
+            } else if (character == '\r') {
+                if (backslashes % 2 == 1) {
+                    line.append(character);
+                    backslashes = 0;
+                } else {
+                    addViolation(result, line);
+                    line.setLength(0);
+                    if (i + 1 < text.length() && text.charAt(i + 1) == '\n') {
+                        i++;
+                    }
+                    backslashes = 0;
+                }
+            } else {
+                line.append(character);
+                backslashes = 0;
+            }
+        }
+        if (line.length() > 0) {
+            addViolation(result, line);
+        }
